package com.hive.gallery;

import android.animation.ValueAnimator;
import android.app.Dialog;
import android.content.Context;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Build;
import android.view.*;
import android.widget.*;

/** Custom modal: native focus, IME and back handling, with a Hive glass card instead of AlertDialog. */
final class GlassDialog extends Dialog {
    final LinearLayout body;private final LinearLayout card,footer;private final boolean light,motion;private final int fg,muted;private final Context ctx;
    GlassDialog(Context context,String title,boolean light,boolean motion){super(context);ctx=context;this.light=light;this.motion=motion;fg=light?0xff17171b:Color.WHITE;muted=light?0xff62636b:0xffb0b0ba;requestWindowFeature(Window.FEATURE_NO_TITLE);
        card=new LinearLayout(context);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(20),dp(18),dp(20),dp(16));card.setBackground(cardBackground(context,light,30));card.setElevation(dp(12));
        View handle=new View(context);GradientDrawable hd=new GradientDrawable();hd.setColor(light?0x42000000:0x66ffffff);hd.setCornerRadius(dp(3));handle.setBackground(hd);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(33),dp(4));hp.gravity=Gravity.CENTER_HORIZONTAL;hp.bottomMargin=dp(17);card.addView(handle,hp);
        TextView heading=text(title,24,fg,true);heading.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams titleLp=new LinearLayout.LayoutParams(-1,-2);titleLp.bottomMargin=dp(14);card.addView(heading,titleLp);
        ScrollView scroll=new ScrollView(context){@Override protected void onMeasure(int ws,int hs){int limit=Math.max(dp(100),Math.min(dp(520),(int)(getResources().getDisplayMetrics().heightPixels*.55f)));int mode=View.MeasureSpec.getMode(hs),size=View.MeasureSpec.getSize(hs);super.onMeasure(ws,View.MeasureSpec.makeMeasureSpec(mode==View.MeasureSpec.UNSPECIFIED?limit:Math.min(size,limit),View.MeasureSpec.AT_MOST));}};scroll.setVerticalScrollBarEnabled(false);scroll.setFillViewport(false);scroll.setClipToPadding(false);body=new LinearLayout(context);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body,new ScrollView.LayoutParams(-1,-2));card.addView(scroll,new LinearLayout.LayoutParams(-1,-2));
        footer=new LinearLayout(context);footer.setOrientation(LinearLayout.HORIZONTAL);footer.setGravity(Gravity.CENTER);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,-2);fp.topMargin=dp(16);card.addView(footer,fp);setContentView(card);setCanceledOnTouchOutside(true);
        Window w=getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);w.setDimAmount(.48f);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);w.setGravity(Gravity.CENTER);w.setWindowAnimations(0);if(Build.VERSION.SDK_INT>=31){w.addFlags(WindowManager.LayoutParams.FLAG_BLUR_BEHIND);WindowManager.LayoutParams a=w.getAttributes();a.setBlurBehindRadius(dp(18));w.setAttributes(a);w.setBackgroundBlurRadius(dp(24));}}
    }
    private int dp(float n){return Math.round(n*ctx.getResources().getDisplayMetrics().density);}
    static GradientDrawable cardBackground(Context c,boolean light,float r){float d=c.getResources().getDisplayMetrics().density;GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,light?new int[]{0xeaffffff,0xdcf0f1f5,0xe5ffffff}:new int[]{0xde2c2d33,0xe218191e,0xde24252c});g.setCornerRadius(r*d);g.setStroke(Math.max(1,Math.round(d)),light?0xddffffff:0x55ffffff);return g;}
    private TextView text(String value,float size,int color,boolean bold){TextView t=new TextView(ctx);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setIncludeFontPadding(false);t.setGravity(Gravity.CENTER_VERTICAL);if(bold)t.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));return t;}
    private GradientDrawable pill(boolean primary){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,primary?(light?new int[]{0xff22232a,0xff3b3d47}:new int[]{0xfff6f6f9,0xffd8dbe3}):(light?new int[]{0x16000000,0x08000000}:new int[]{0x26ffffff,0x0cffffff}));g.setCornerRadius(dp(22));g.setStroke(dp(1),light?0x24000000:0x44ffffff);return g;}
    private ImageView icon(int id,int color){ImageView v=new ImageView(ctx);v.setImageResource(id);v.setImageTintList(ColorStateList.valueOf(color));v.setScaleType(ImageView.ScaleType.FIT_CENTER);return v;}
    void option(int id,String title,String detail,boolean selected,Runnable run){LinearLayout row=new LinearLayout(ctx);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(12),dp(12),dp(12));row.setMinimumHeight(dp(51));GradientDrawable bg=new GradientDrawable();bg.setColor(selected?(light?0x20000000:0x25ffffff):(light?0x08000000:0x0bffffff));bg.setCornerRadius(dp(17));if(selected)bg.setStroke(dp(1),light?0x44000000:0x55ffffff);row.setBackground(bg);row.setClickable(true);row.setFocusable(true);row.setContentDescription(title+(detail==null?"":", "+detail)+(selected?", selected":""));row.setOnClickListener(v->run.run());row.addView(icon(id,fg),new LinearLayout.LayoutParams(dp(22),dp(22)));LinearLayout texts=new LinearLayout(ctx);texts.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.leftMargin=dp(12);tp.rightMargin=dp(7);row.addView(texts,tp);TextView main=text(title,14,fg,true);main.setMaxLines(2);main.setEllipsize(android.text.TextUtils.TruncateAt.END);texts.addView(main,new LinearLayout.LayoutParams(-1,-2));if(detail!=null){TextView sub=text(detail,12,muted,false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(5);texts.addView(sub,sp);}row.addView(icon(selected?R.drawable.ic_check:R.drawable.ic_chevron_right,muted),new LinearLayout.LayoutParams(dp(18),dp(18)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=dp(6);body.addView(row,rp);}
    void message(String msg){TextView v=text(msg,14,fg,false);v.setLineSpacing(dp(3),1);v.setPadding(dp(3),dp(5),dp(3),dp(12));body.addView(v,new LinearLayout.LayoutParams(-1,-2));}
    void field(String label,String value){LinearLayout row=new LinearLayout(ctx);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(3),dp(10),dp(3),dp(10));row.addView(text(label,11,muted,false));TextView data=text(value,14,fg,true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(5);row.addView(data,lp);body.addView(row);View line=new View(ctx);line.setBackgroundColor(light?0x16000000:0x20ffffff);body.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}
    void buttons(String secondary,Runnable left,String primary,Runnable right){footer.removeAllViews();if(secondary!=null)addButton(secondary,false,left);if(primary!=null)addButton(primary,true,right);}
    private void addButton(String title,boolean primary,Runnable action){TextView b=text(title,14,primary?(light?Color.WHITE:0xff15151a):fg,true);b.setGravity(Gravity.CENTER);b.setBackground(pill(primary));b.setClickable(true);b.setFocusable(true);b.setOnClickListener(v->{dismiss();if(action!=null)action.run();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(45),1);if(footer.getChildCount()>0)lp.leftMargin=dp(8);footer.addView(b,lp);}
    @Override public void show(){super.show();Window w=getWindow();if(w!=null){int width=Math.min(dp(430),ctx.getResources().getDisplayMetrics().widthPixels-dp(36));w.setLayout(Math.max(dp(240),width),WindowManager.LayoutParams.WRAP_CONTENT);}if(motion&&ValueAnimator.areAnimatorsEnabled()){card.setAlpha(0);card.setScaleX(.96f);card.setScaleY(.96f);card.setTranslationY(dp(12));card.animate().alpha(1).scaleX(1).scaleY(1).translationY(0).setDuration(260).setInterpolator(new android.view.animation.DecelerateInterpolator(1.5f)).start();}}
}
